"""Export strict MashMap homology edges for evidence-free dual phasing.

The Hi-C pipeline already centralizes MashMap interval aggregation and its
clear-best homology filters in ``scaffolding/match_graph.py``.  This wrapper
intentionally reuses that implementation so dual and contact phasing do not
drift toward different definitions of homologous sequence.
"""

import argparse
import logging
import os
import sys

import networkx as nx

SCRIPT_DIR = os.path.abspath(os.path.dirname(__file__))
sys.path.insert(0, os.path.join(SCRIPT_DIR, "scaffolding"))

import graph_functions as gf  # noqa: E402
import match_graph  # noqa: E402


MIN_ALIGNMENT = 50_000
CLEAR_HOMOLOGY = 250_000
HOMOLOGY_WEIGHT = -1


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Select strict homologous node pairs from Verkko MashMap output."
    )
    parser.add_argument("graph", help="HPC no-sequence GFA used for phasing")
    parser.add_argument("mashmap", help="HPC all-vs-all MashMap output")
    parser.add_argument("output", help="Output TSV of strict homologous pairs")
    args = parser.parse_args()

    graph = nx.Graph()
    gf.load_indirect_graph(args.graph, graph)
    matches = match_graph.MatchGraph(
        args.mashmap,
        graph,
        HOMOLOGY_WEIGHT,
        CLEAR_HOMOLOGY,
        MIN_ALIGNMENT,
    ).getMatchGraph()

    strict_edges = []
    for first, second, data in matches.edges(data=True):
        if data.get("weight", 0) < 0:
            strict_edges.append((first, second, int(data["homology_len"])))
    strict_edges.sort()

    with open(args.output, "w", encoding="utf-8") as output:
        output.write("node1\tnode2\thomology_length\n")
        for first, second, homology_length in strict_edges:
            output.write(f"{first}\t{second}\t{homology_length}\n")

    logging.info("Exported %d strict homology pairs", len(strict_edges))


if __name__ == "__main__":
    main()
